#!/usr/bin/env node
// PreToolUse Claude Code hook for the level-2 reviewer (registered in the agent's own frontmatter,
// see docs/tutorials/level-2/examples/reviewer-v1-restricted.md). It is not a Frappe hook.
//
// Allows only:
//   git diff | git log | git show | git status  (read-only git)
//   bench --site test.localhost run-tests [--app spice_lite | --module <dotted> [--test <name>]... | --doctype "<DocType>"] [--failfast]
//     optionally prefixed by `cd <bench dir> && ` and optionally piped `2>&1 | python3 <...>/parse_bench_tests.py`
// Blocks everything else with exit code 2, and names the dangerous bench commands explicitly:
// console and execute run arbitrary Python as Administrator on the site (execute commits), migrate
// changes the schema and runs patches, and the rest change site config or data.
//
// Why a Claude Code hook: `tools` can only include or drop the whole Bash tool, and a
// `disallowedTools` entry such as `Bash(bench *)` removes all of Bash. The hook narrows Bash to a few
// commands whatever permission mode the parent session is in.
//
// Input: hook JSON on stdin (tool_name, tool_input.command, agent_type, ...). Exit 0 = continue to the
// normal permission checks; exit 2 = block, stderr is shown to the subagent. Fails closed.

import { pathToFileURL } from "node:url";
import { resolve } from "node:path";

const BENCH_DIR = process.env.SPICE_BENCH_DIR || "/home/user/frappe-bench";
const SITE = "test.localhost";
const GIT_READ = /^git (diff|log|show|status)( |$)/;
const GIT_RISKY = /(^| )(--output(=| |$)|--ext-diff|--textconv|-c )/;
const SHELL_META = /[;&|<>`\n\r]|\$\(/;
const DANGEROUS_BENCH = /^bench (--\S+ )*(--site \S+ )?(console|execute|migrate|mariadb|postgres|db-console|drop-site|reinstall|restore|set-config|set-admin-password|add-system-manager|install-app|uninstall-app|run-patch|destroy-all-sessions|serve|backup|export-fixtures|trim-database|clear-cache)\b/;
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const CD_PREFIX = new RegExp(`^cd ${esc(BENCH_DIR)} && `);
const PARSER_SUFFIX = / 2>&1 \| python3 [A-Za-z0-9_.\/-]*\.claude\/skills\/run-tests\/scripts\/parse_bench_tests\.py$/;

function runTestsArgsOk(rest) {
  // rest: the text after "bench --site test.localhost run-tests"
  const tokens = rest.match(/"[^"]*"|\S+/g) || [];
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    const v = tokens[i + 1];
    if (t === "--failfast") continue;
    if (t === "--app" && v === "spice_lite") { i++; continue; }
    if (t === "--module" && /^spice_lite(\.[a-z0-9_]+)+$/.test(v || "")) { i++; continue; }
    if (t === "--test" && /^test_[a-z0-9_]+$/.test(v || "")) { i++; continue; }
    if (t === "--doctype" && /^("SL [A-Za-z ]+"|'SL [A-Za-z ]+')$/.test(v || "")) { i++; continue; }
    return false;
  }
  return true;
}

export function decide(input) {
  if (!input || typeof input !== "object") return { allow: false, reason: "hook input is not a JSON object" };
  if (input.tool_name !== "Bash") return { allow: true };
  let command = String(input.tool_input?.command ?? "").trim().replace(/[ \t]+/g, " ");
  if (!command) return { allow: false, reason: "empty Bash command" };

  // The two sanctioned compound forms are stripped before the metacharacter check.
  const bare = command.replace(CD_PREFIX, "");
  const isBench = bare.startsWith("bench ");
  if (isBench) command = bare.replace(PARSER_SUFFIX, "");

  if (SHELL_META.test(command)) return { allow: false, reason: `shell operators are not allowed for the reviewer: ${command}` };

  if (GIT_READ.test(command)) {
    if (GIT_RISKY.test(command)) return { allow: false, reason: `git option not allowed for the reviewer: ${command}` };
    return { allow: true };
  }
  if (DANGEROUS_BENCH.test(command)) {
    return {
      allow: false,
      reason: `bench console/execute/migrate and other site-changing bench commands are never allowed for the reviewer; blocked: ${command}`,
    };
  }
  const prefix = `bench --site ${SITE} run-tests`;
  if (command === prefix || command.startsWith(prefix + " ")) {
    if (runTestsArgsOk(command.slice(prefix.length))) return { allow: true };
    return { allow: false, reason: `run-tests arguments not allowed (use --app spice_lite, --module spice_lite.x [--test test_x], --doctype "SL X"): ${command}` };
  }
  return {
    allow: false,
    reason: `reviewer may only run git diff/log/show/status and bench --site ${SITE} run-tests; blocked: ${command}`,
  };
}

async function main() {
  let raw = "";
  for await (const chunk of process.stdin) raw += chunk;
  let input;
  try {
    input = JSON.parse(raw);
  } catch {
    process.stderr.write("reviewer-bash-guard: could not parse hook input; blocking\n");
    process.exit(2);
  }
  const { allow, reason } = decide(input);
  if (!allow) {
    process.stderr.write(`reviewer-bash-guard: ${reason}\n`);
    process.exit(2);
  }
  process.exit(0);
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) main();

// Tests for reviewer-bash-guard.mjs. Run from AI-SDLC-frappe/:
//   node --test docs/tutorials/level-2/examples/reviewer-bash-guard.test.mjs
import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { decide } from "./reviewer-bash-guard.mjs";

const HOOK = join(dirname(fileURLToPath(import.meta.url)), "reviewer-bash-guard.mjs");
const PARSER = "/home/user/artifacts/AI-SDLC-frappe/.claude/skills/run-tests/scripts/parse_bench_tests.py";

function run(input) {
  const stdin = typeof input === "string" ? input : JSON.stringify(input);
  return spawnSync(process.execPath, [HOOK], { input: stdin, encoding: "utf8", env: { ...process.env, SPICE_BENCH_DIR: "" } });
}

function bash(command) {
  return {
    session_id: "test",
    hook_event_name: "PreToolUse",
    permission_mode: "default",
    agent_type: "reviewer",
    tool_name: "Bash",
    tool_input: { command, description: "test" },
  };
}

const allowed = (c) => decide(bash(c)).allow;

test("allows read-only git commands", () => {
  for (const c of ["git diff", "git diff HEAD -- sample-app", "git log --oneline -5", "git show HEAD:sample-app/spice_lite/spice_lite/hooks.py", "git status --short"]) {
    assert.equal(allowed(c), true, c);
  }
});

test("allows bench run-tests on test.localhost with safe selections", () => {
  for (const c of [
    "bench --site test.localhost run-tests --app spice_lite",
    "bench --site test.localhost run-tests --module spice_lite.tests.test_fhir_api",
    "bench --site test.localhost run-tests --module spice_lite.tests.test_fhir_api --test test_lastn_returns_latest_per_patient",
    'bench --site test.localhost run-tests --doctype "SL Observation"',
    "cd /home/user/frappe-bench && bench --site test.localhost run-tests --app spice_lite",
    `cd /home/user/frappe-bench && bench --site test.localhost run-tests --app spice_lite 2>&1 | python3 ${PARSER}`,
  ]) {
    assert.equal(allowed(c), true, c);
  }
});

test("blocks the dangerous bench commands by name", () => {
  for (const c of [
    "bench --site test.localhost console",
    "bench --site test.localhost execute spice_lite.demo.seed_demo",
    "bench --site test.localhost migrate",
    "bench --verbose --site test.localhost console",
    "cd /home/user/frappe-bench && bench --site test.localhost execute frappe.db.commit",
    "bench --site test.localhost set-config allow_tests 0",
    "bench drop-site test.localhost",
    "bench --site test.localhost reinstall --yes",
    "bench --site test.localhost postgres",
  ]) {
    const d = decide(bash(c));
    assert.equal(d.allow, false, c);
    assert.match(d.reason, /bench console\/execute\/migrate/, c);
  }
});

test("blocks other sites, other run-tests arguments and non-git commands", () => {
  for (const c of [
    "bench --site mariadb.localhost run-tests --app spice_lite",
    "bench --site test.localhost run-tests --app frappe",
    "bench --site test.localhost run-tests --module os.system",
    "bench --site test.localhost run-tests --junit-xml-output /tmp/x.xml",
    "bench --verbose --site test.localhost run-tests --app spice_lite",
    "cat sites/test.localhost/site_config.json",
    "python3 -c 'import frappe'",
    "git commit -am wip",
    "git push",
    "cd /tmp && bench --site test.localhost run-tests --app spice_lite",
  ]) {
    assert.equal(allowed(c), false, c);
  }
});

test("blocks chaining, redirection and substitution, including inside the allowed forms", () => {
  for (const c of [
    "git diff; bench --site test.localhost console",
    "git diff && git push",
    "git diff | tee out.txt",
    "git diff > review.txt",
    "git log $(whoami)",
    "bench --site test.localhost run-tests --app spice_lite; rm -rf sites",
    "bench --site test.localhost run-tests --app spice_lite 2>&1 | sh",
    "bench --site test.localhost run-tests --app spice_lite 2>&1 | python3 $(curl x)/.claude/skills/run-tests/scripts/parse_bench_tests.py",
    "bench --site test.localhost run-tests --app spice_lite > /tmp/out",
    "git status\nbench --site test.localhost migrate",
  ]) {
    assert.equal(allowed(c), false, c);
  }
});

test("blocks git options that write files or run programs", () => {
  for (const c of ["git diff --output=/tmp/x", "git diff --ext-diff", "git log --textconv", "git -c core.pager=sh diff"]) {
    assert.equal(allowed(c), false, c);
  }
});

test("ignores other tools", () => {
  assert.equal(decide({ tool_name: "Read", tool_input: { file_path: "sample-app/spice_lite/spice_lite/hooks.py" } }).allow, true);
});

test("process exit codes: 0 allow, 2 block with reason on stderr, 2 on bad JSON", () => {
  assert.equal(run(bash("git diff")).status, 0);
  const blocked = run(bash("bench --site test.localhost console"));
  assert.equal(blocked.status, 2);
  assert.match(blocked.stderr, /^reviewer-bash-guard: bench console\/execute\/migrate and other site-changing bench commands are never allowed for the reviewer; blocked: bench --site test.localhost console\n$/);
  assert.equal(run("not json").status, 2);
});
